(() => {
  "use strict";
  const $ = s => document.querySelector(s);
  const OVERLAY_HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<title>Chat Overlay<\/title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Bungee&family=Inter:wght@500;600;700;800&family=Nunito:wght@600;700;800&family=Press+Start+2P&family=Rubik:wght@500;700&family=VT323&display=swap\" rel=\"stylesheet\">\n<style>\n  html,body{margin:0;height:100%;background:transparent;overflow:hidden}\n  body{--scale:1;--bga:.86;--accent:#2ff3ff;--card-rgb:18,8,34;--gap:10px;color:#fff}\n\n  /* =============== layout =============== */\n  #chat{\n    position:absolute;inset:0;\n    display:flex;flex-direction:column;justify-content:flex-end;align-items:flex-start;\n    gap:calc(var(--gap)*var(--scale));\n    padding:calc(14px*var(--scale));\n    box-sizing:border-box;overflow:hidden;\n  }\n  body.v-top #chat{justify-content:flex-start}\n  body.o-newfirst #chat{flex-direction:column-reverse;justify-content:flex-start}\n  body.o-newfirst.v-top #chat{justify-content:flex-end}\n  body.a-center #chat{align-items:center}\n  body.a-right #chat{align-items:flex-end}\n  body.w-full #chat{align-items:stretch}\n  body.a-center .msg{text-align:center}\n  body.a-center .head{justify-content:center}\n\n  .msg{\n    position:relative;max-width:100%;box-sizing:border-box;overflow-wrap:anywhere;\n    --ucol:var(--accent);\n    font-size:calc(18px*var(--scale));line-height:1.35;\n    transform-origin:left bottom;\n  }\n  body.a-right .msg{transform-origin:right bottom}\n  body.a-center .msg{transform-origin:center bottom}\n  body.usercols .msg{--ucol:var(--user-col,var(--accent))}\n  body .msg.event{--ucol:var(--accent)}\n  .head{display:flex;align-items:center;gap:calc(5px*var(--scale));flex-wrap:wrap}\n  .name{color:var(--ucol)}\n  .msg.action .text{font-style:italic;color:var(--ucol)}\n  .emote{height:calc(28px*var(--scale)*var(--escale,1));vertical-align:middle;margin:calc(-4px*var(--scale)) 1px}\n  .emote-only .emote{height:calc(48px*var(--scale)*var(--escale,1))}\n  .ecount{font-weight:800;font-size:.8em;margin:0 .25em 0 .1em;opacity:.9}\n  /* highlighted chatters */\n  .msg.reg{outline:calc(2px*var(--scale)) solid var(--reg);outline-offset:calc(3px*var(--scale))}\n  .msg.reg .name::before{content:\"\\2605  \";color:var(--reg)}\n  .theme-8bit .msg.reg{--frame:var(--reg);outline:none}\n  .theme-neon .msg.reg{border-color:var(--reg)}\n  /* emote combos */\n  #fx{position:absolute;inset:0;pointer-events:none;z-index:4;overflow:hidden}\n  .combo{position:absolute;transform:translate(-50%,-50%);text-align:center;animation:comboIn .5s cubic-bezier(.2,1.8,.4,1) both}\n  .combo img{display:block;margin:0 auto;height:calc(110px*var(--scale)*var(--escale,1));filter:drop-shadow(0 calc(4px*var(--scale)) 0 rgba(0,0,0,.6))}\n  .combo .ccount{margin-top:calc(4px*var(--scale));font:calc(26px*var(--scale)) Bungee,Rubik,sans-serif;color:#fff;\n    -webkit-text-stroke:calc(1.5px*var(--scale)) #000;text-shadow:calc(3px*var(--scale)) calc(3px*var(--scale)) 0 var(--accent)}\n  .theme-8bit .combo .ccount{font-family:\"Press Start 2P\",monospace;font-size:calc(18px*var(--scale))}\n  .theme-terminal .combo .ccount{font-family:VT323,monospace;font-size:calc(34px*var(--scale))}\n  .combo.bump .ccount{animation:bump .3s ease}\n  .combo.bye{animation:comboOut .6s ease-in forwards}\n  @keyframes comboIn{0%{opacity:0;transform:translate(-50%,-50%) scale(.2) rotate(-20deg)}100%{opacity:1;transform:translate(-50%,-50%)}}\n  @keyframes comboOut{to{opacity:0;transform:translate(-50%,-110%) scale(.8)}}\n  @keyframes bump{50%{transform:scale(1.35)}}\n  .mention{color:#111;background:var(--accent);border-radius:4px;padding:0 4px;font-weight:700}\n  .link{opacity:.65;font-style:italic}\n  .badge{height:calc(18px*var(--scale));width:calc(18px*var(--scale));vertical-align:middle}\n  .chip{\n    font:800 calc(10px*var(--scale)) Inter,sans-serif;letter-spacing:.3px;\n    padding:calc(2px*var(--scale)) calc(6px*var(--scale));\n    border-radius:calc(5px*var(--scale));color:#120822;line-height:1.3;\n  }\n  .chip.host{background:#ff4fd8}\n  .chip.mod{background:#3dff8a}\n  .chip.vip{background:#ff8af0}\n  .chip.sub{background:#2ff3ff}\n  .chip.first{background:#ffe14d}\n  .chip.bits{background:#c48bff}\n  .msg.first{border-style:dashed !important}\n  .evline{font-weight:800;color:var(--accent);margin-bottom:calc(2px*var(--scale))}\n  .msg.event{outline:calc(2px*var(--scale)) dashed var(--accent);outline-offset:calc(3px*var(--scale))}\n  .msg.hl{outline:calc(2px*var(--scale)) solid var(--accent);outline-offset:calc(3px*var(--scale));\n    filter:drop-shadow(0 0 calc(8px*var(--scale)) color-mix(in srgb,var(--accent) 60%,transparent))}\n\n  /* =============== animations =============== */\n  body{--slide:-60px;--slidey:0px}\n  body.a-right{--slide:60px}\n  body.a-center{--slide:0px;--slidey:24px}\n  body.anim-pop .msg{animation:pop .45s cubic-bezier(.2,1.6,.4,1) both}\n  body.anim-slide .msg{animation:slide .35s cubic-bezier(.2,.9,.3,1.1) both}\n  body.anim-fade .msg{animation:fade .5s ease both}\n  @keyframes pop{0%{opacity:0;transform:translateY(30px) scale(.6)}100%{opacity:1;transform:none}}\n  @keyframes slide{0%{opacity:0;transform:translate(var(--slide),var(--slidey))}100%{opacity:1;transform:none}}\n  @keyframes fade{0%{opacity:0}100%{opacity:1}}\n  body .msg.out{animation:out .45s ease-in forwards}\n  @keyframes out{to{opacity:0;transform:scale(.92)}}\n  body.tilt .msg:nth-child(odd){rotate:-.6deg}\n  body.tilt .msg:nth-child(even){rotate:.6deg}\n\n  /* =============== theme: WizHardz Neon =============== */\n  body.theme-neon{--accent:#2ff3ff;--card-rgb:18,8,34}\n  .theme-neon #chat{font-family:Rubik,sans-serif;color:#f4ecff}\n  .theme-neon .msg{\n    background:rgba(var(--card-rgb),var(--bga));\n    border:calc(3px*var(--scale)) solid var(--ucol);\n    border-radius:calc(14px*var(--scale)) calc(14px*var(--scale)) calc(14px*var(--scale)) calc(4px*var(--scale));\n    box-shadow:calc(5px*var(--scale)) calc(5px*var(--scale)) 0 #b14dff,\n               0 0 calc(14px*var(--scale)) color-mix(in srgb,var(--ucol) 45%,transparent);\n    padding:calc(8px*var(--scale)) calc(12px*var(--scale)) calc(10px*var(--scale));\n  }\n  body.theme-neon.a-right .msg{\n    border-radius:calc(14px*var(--scale)) calc(14px*var(--scale)) calc(4px*var(--scale)) calc(14px*var(--scale));\n    box-shadow:calc(-5px*var(--scale)) calc(5px*var(--scale)) 0 #b14dff,\n               0 0 calc(14px*var(--scale)) color-mix(in srgb,var(--ucol) 45%,transparent);\n  }\n  body.theme-neon.a-center .msg{border-radius:calc(14px*var(--scale))}\n  .theme-neon .head{margin-bottom:calc(3px*var(--scale))}\n  .theme-neon .name{font-family:Bungee,sans-serif;font-size:calc(17px*var(--scale));\n    text-shadow:calc(2px*var(--scale)) calc(2px*var(--scale)) 0 #000;letter-spacing:.5px}\n  .theme-neon .text{font-weight:500}\n  .theme-neon .chip{font-family:Bungee,sans-serif;font-weight:400;box-shadow:calc(2px*var(--scale)) calc(2px*var(--scale)) 0 #000}\n  .theme-neon .badge{filter:drop-shadow(calc(1.5px*var(--scale)) calc(1.5px*var(--scale)) 0 #000)}\n  .theme-neon .evline{font-family:Bungee,sans-serif;font-weight:400;font-size:calc(14px*var(--scale));text-shadow:calc(2px*var(--scale)) calc(2px*var(--scale)) 0 #000}\n\n  /* =============== theme: Clean (basic) =============== */\n  body.theme-clean{--accent:#8b7bff;--card-rgb:18,18,24}\n  .theme-clean #chat{font-family:Inter,system-ui,sans-serif;color:#f1f1f5}\n  .theme-clean .msg{\n    background:rgba(var(--card-rgb),var(--bga));\n    border-radius:calc(10px*var(--scale));\n    border-left:calc(4px*var(--scale)) solid var(--ucol);\n    padding:calc(7px*var(--scale)) calc(12px*var(--scale)) calc(8px*var(--scale));\n    box-shadow:0 calc(2px*var(--scale)) calc(10px*var(--scale)) rgba(0,0,0,.25);\n  }\n  body.theme-clean.a-right .msg{border-left:0;border-right:calc(4px*var(--scale)) solid var(--ucol)}\n  body.theme-clean.a-center .msg{border-left:0;border-top:calc(3px*var(--scale)) solid var(--ucol)}\n  .theme-clean .head{margin-bottom:calc(2px*var(--scale))}\n  .theme-clean .name{font-weight:700;font-size:calc(15px*var(--scale))}\n  .theme-clean .text{font-weight:500}\n\n  /* =============== theme: Minimal (no boxes) =============== */\n  body.theme-minimal{--accent:#ffffff;--card-rgb:0,0,0;--gap:4px}\n  .theme-minimal #chat{font-family:Inter,system-ui,sans-serif;color:#fff}\n  .theme-minimal .msg{\n    background:rgba(var(--card-rgb),var(--bga));\n    padding:calc(3px*var(--scale)) calc(8px*var(--scale));\n    border-radius:calc(6px*var(--scale));font-weight:600;\n    text-shadow:0 0 calc(3px*var(--scale)) #000,0 calc(1px*var(--scale)) calc(2px*var(--scale)) #000,0 0 1px #000;\n  }\n  .theme-minimal .head{display:inline-flex;margin-right:calc(6px*var(--scale));vertical-align:baseline}\n  .theme-minimal .name{font-weight:800}\n  .theme-minimal .msg:not(.action) .name::after{content:\":\";color:#fff}\n  .theme-minimal .text{display:inline}\n  .theme-minimal .evline{display:block}\n  .theme-minimal .mention{text-shadow:none}\n\n  /* =============== theme: Bubbles =============== */\n  body.theme-bubbles{--accent:#7c5cff;--card-rgb:255,255,255}\n  .theme-bubbles #chat{font-family:Nunito,system-ui,sans-serif;color:#1d1b2e}\n  .theme-bubbles .msg{\n    background:rgba(var(--card-rgb),var(--bga));\n    border-radius:calc(20px*var(--scale)) calc(20px*var(--scale)) calc(20px*var(--scale)) calc(6px*var(--scale));\n    padding:calc(8px*var(--scale)) calc(14px*var(--scale)) calc(10px*var(--scale));\n    box-shadow:0 calc(4px*var(--scale)) 0 rgba(0,0,0,.18);\n  }\n  body.theme-bubbles.a-right .msg{border-radius:calc(20px*var(--scale)) calc(20px*var(--scale)) calc(6px*var(--scale)) calc(20px*var(--scale))}\n  body.theme-bubbles.a-center .msg{border-radius:calc(20px*var(--scale))}\n  .theme-bubbles .head{margin-bottom:calc(4px*var(--scale))}\n  .theme-bubbles .name{background:var(--ucol);color:#14121f;font-weight:800;font-size:calc(13px*var(--scale));\n    padding:calc(1px*var(--scale)) calc(9px*var(--scale));border-radius:99px}\n  .theme-bubbles .text{font-weight:700}\n  .theme-bubbles .msg.action .text{color:inherit}\n  .theme-bubbles .mention{color:#fff}\n\n  /* =============== theme: Retro Terminal =============== */\n  body.theme-terminal{--accent:#39ff88;--card-rgb:4,12,7}\n  .theme-terminal #chat{font-family:VT323,ui-monospace,monospace;color:#b9ffd3}\n  .theme-terminal .msg{\n    font-size:calc(24px*var(--scale));line-height:1.1;\n    background:repeating-linear-gradient(0deg,rgba(0,0,0,.2) 0 2px,transparent 2px 4px),rgba(var(--card-rgb),var(--bga));\n    border:calc(2px*var(--scale)) solid var(--accent);border-radius:3px;\n    padding:calc(6px*var(--scale)) calc(12px*var(--scale));\n    text-shadow:0 0 6px rgba(57,255,136,.55);\n    box-shadow:0 0 calc(12px*var(--scale)) color-mix(in srgb,var(--accent) 30%,transparent);\n  }\n  .theme-terminal .name::before{content:\"> \";color:var(--accent)}\n  .theme-terminal .chip{font-family:VT323,monospace;font-weight:400;font-size:calc(16px*var(--scale))}\n\n  /* =============== theme: 8-Bit Arcade =============== */\n  body.theme-8bit{--accent:#f8b800;--card-rgb:16,16,58;--gap:18px;--frame:#fcfcfc}\n  .theme-8bit #chat{font-family:\"Press Start 2P\",monospace;color:#fcfcfc;padding:calc(20px*var(--scale))}\n  .theme-8bit .msg{\n    --px:calc(4px*var(--scale));\n    font-size:calc(12px*var(--scale));line-height:1.75;\n    background:rgba(var(--card-rgb),var(--bga));\n    padding:calc(var(--px)*3) calc(var(--px)*4);\n    margin:var(--px);\n    /* notched pixel frame: frame colour on top, black outline behind */\n    box-shadow:\n      0 calc(var(--px)*-1) 0 0 var(--frame), 0 var(--px) 0 0 var(--frame),\n      calc(var(--px)*-1) 0 0 0 var(--frame), var(--px) 0 0 0 var(--frame),\n      0 calc(var(--px)*-2) 0 0 #000, 0 calc(var(--px)*2) 0 0 #000,\n      calc(var(--px)*-2) 0 0 0 #000, calc(var(--px)*2) 0 0 0 #000,\n      calc(var(--px)*2) calc(var(--px)*3) 0 0 rgba(0,0,0,.45);\n    image-rendering:pixelated;\n  }\n  .theme-8bit .msg.event,.theme-8bit .msg.hl{--frame:var(--accent);outline:none;filter:none}\n  .theme-8bit .msg.first{border:0 !important;--frame:#00e8d8}\n  .theme-8bit .head{margin-bottom:calc(6px*var(--scale))}\n  .theme-8bit .name{text-transform:uppercase;text-shadow:calc(2px*var(--scale)) calc(2px*var(--scale)) 0 #000}\n  .theme-8bit .text{text-shadow:calc(2px*var(--scale)) calc(2px*var(--scale)) 0 #000}\n  .theme-8bit .chip{font:calc(8px*var(--scale)) \"Press Start 2P\",monospace;border-radius:0;padding:calc(3px*var(--scale)) calc(4px*var(--scale));\n    box-shadow:calc(2px*var(--scale)) calc(2px*var(--scale)) 0 #000}\n  .theme-8bit .badge{image-rendering:pixelated}\n  .theme-8bit .mention{border-radius:0;color:#000;text-shadow:none}\n  .theme-8bit .evline{font-weight:400;text-shadow:calc(2px*var(--scale)) calc(2px*var(--scale)) 0 #000;margin-bottom:calc(6px*var(--scale))}\n  .theme-8bit .emote{height:calc(26px*var(--scale))}\n  .theme-8bit .emote-only .emote{height:calc(44px*var(--scale))}\n  .theme-8bit .msg:last-child .text::after{content:\" \\25BC\";color:var(--accent);animation:blink8 .8s steps(1) infinite}\n  @keyframes blink8{50%{opacity:0}}\n  body.theme-8bit.anim-pop .msg{animation:pop8 .4s steps(4) both}\n  body.theme-8bit.anim-slide .msg{animation-timing-function:steps(6)}\n  body.theme-8bit.anim-fade .msg{animation-timing-function:steps(4)}\n  body.theme-8bit .msg.out{animation:out .4s steps(4) forwards}\n  @keyframes pop8{0%{opacity:0;transform:translateY(16px) scale(.5)}100%{opacity:1;transform:none}}\n\n  /* =============== status + gear =============== */\n  #status{\n    position:absolute;top:10px;left:10px;max-width:calc(100% - 80px);\n    font:700 13px Rubik,sans-serif;color:#fff;\n    background:rgba(0,0,0,.75);padding:6px 10px;border-radius:8px;\n    transition:opacity .6s;z-index:5;\n  }\n  #status.hide{opacity:0}\n  #gear{\n    position:absolute;top:10px;right:10px;z-index:10;\n    width:44px;height:44px;border-radius:12px;border:3px solid #2ff3ff;\n    background:#1a0b30;color:#2ff3ff;font-size:24px;cursor:pointer;\n    box-shadow:4px 4px 0 #b14dff;opacity:0;transition:opacity .2s;\n  }\n  body:hover #gear{opacity:1}\n\n  /* =============== settings panel =============== */\n  #panel{\n    position:absolute;z-index:20;display:none;flex-direction:column;\n    width:min(510px,calc(100% - 16px));max-height:min(560px,calc(100% - 16px));\n    background:rgba(20,8,38,.97);border:3px solid #2ff3ff;border-radius:14px;\n    box-shadow:5px 5px 0 #b14dff;font:14px Rubik,sans-serif;color:#f4ecff;\n    box-sizing:border-box;\n  }\n  #panel.open{display:flex}\n  #panel.c-t{top:8px} #panel.c-b{bottom:8px}\n  #panel.c-l{left:8px} #panel.c-r{right:8px}\n  .phead{cursor:move;user-select:none}\n  #panel.mini .pbody,#panel.mini .pfoot{display:none}\n  .phead{display:flex;align-items:center;gap:6px;padding:8px 10px;border-bottom:2px solid #3a2361;flex:none}\n  .phead h1{flex:1;margin:0;font:18px Bungee,sans-serif;color:#2ff3ff;text-shadow:2px 2px 0 #b14dff;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n  .ibtn{width:32px;height:32px;flex:none;border-radius:8px;border:2px solid #4b2d7d;background:#0c0418;color:#fff;cursor:pointer;font-size:15px;padding:0}\n  .ibtn:hover{border-color:#2ff3ff}\n  .pbody{overflow:auto;padding:10px 12px 14px;flex:1}\n  .hint{color:#c9b6ea;font-size:12.5px;margin:0 0 10px}\n  #panel fieldset{border:2px solid #3a2361;border-radius:12px;margin:0 0 10px;padding:6px 12px 8px}\n  #panel legend{font:13px Bungee,sans-serif;color:#ff4fd8;padding:0 6px}\n  .row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:5px 0}\n  .row > label:not(.switch){flex:1}\n  .row > label:not(.switch){cursor:pointer}\n  .msg[hidden]{display:none !important}\n  .row small{display:block;color:#a993cf;font-size:12px;font-weight:500}\n  #panel input[type=text],#panel input[type=number],#panel select{\n    font:600 14px Rubik,sans-serif;color:#f4ecff;background:#0c0418;\n    border:2px solid #4b2d7d;border-radius:8px;padding:6px 8px;\n  }\n  #panel select{max-width:55%}\n  #panel input[type=text].wide{width:100%;box-sizing:border-box;margin-top:4px}\n  #panel input[type=number]{width:72px}\n  #panel input[type=range]{width:130px;accent-color:#b14dff}\n  #panel input:focus,#panel select:focus{outline:none;border-color:#2ff3ff}\n  .val{display:inline-block;min-width:40px;text-align:right;font-size:13px;color:#2ff3ff}\n  .switch{position:relative;width:46px;height:26px;flex:none}\n  .switch input{opacity:0;width:0;height:0;position:absolute}\n  .switch span{position:absolute;inset:0;background:#2b1a48;border-radius:20px;cursor:pointer;transition:.2s;border:2px solid #4b2d7d}\n  .switch span::after{content:\"\";position:absolute;width:18px;height:18px;left:2px;top:2px;background:#8a76ad;border-radius:50%;transition:.2s}\n  .switch input:checked + span{background:#b14dff;border-color:#2ff3ff}\n  .switch input:checked + span::after{transform:translateX(20px);background:#fff}\n  .swatches{display:flex;gap:6px;flex-wrap:wrap;align-items:center;margin-top:6px}\n  .sw{width:24px;height:24px;border-radius:50%;border:2px solid #000;cursor:pointer;box-shadow:0 0 0 2px #4b2d7d;padding:0}\n  .sw.def{background:conic-gradient(#2ff3ff,#b14dff,#ff4fd8,#ffe14d,#2ff3ff)}\n  .sw.sel{box-shadow:0 0 0 3px #fff}\n  #s_accent{width:86px}\n  .pfoot{display:flex;gap:6px;flex-wrap:wrap;padding:10px 12px;border-top:2px solid #3a2361;flex:none}\n  .btn{\n    font:12px Bungee,sans-serif;cursor:pointer;border:2px solid #000;border-radius:9px;\n    padding:6px 9px;box-shadow:2px 2px 0 #000;color:#120822;background:#2ff3ff;\n  }\n  .btn.alt{background:#c9b6ea}\n  .btn.warn{background:#ff8a8a}\n  .btn:active{transform:translate(2px,2px);box-shadow:1px 1px 0 #000}\n  .mode{margin:6px 0 2px;font-size:13px;font-weight:700;color:#3dff8a}\n  .mode[data-state=none],.mode[data-state=bad]{color:#ff8a8a}\n  .mode[data-state=connecting],.mode[data-state=retrying]{color:#ffe14d}\n  .note{color:#ffe14d;font-size:12.5px;margin:4px 0 0}\n  #linkbox{width:100%;box-sizing:border-box;font:12px monospace;color:#c9b6ea;background:#0c0418;border:2px solid #4b2d7d;border-radius:8px;padding:6px;resize:none;height:56px}\n  .linkrow{display:flex;gap:8px;align-items:stretch;margin-top:6px}\n  .linkrow textarea{flex:1;min-width:0}\n  .linkrow .btn{flex:none}\n<\/style>\n<\/head>\n<body>\n<div id=\"chat\"><\/div>\n<div id=\"fx\"><\/div>\n<div id=\"status\">starting\u2026<\/div>\n<button id=\"gear\" title=\"Settings\">\u2699<\/button>\n\n<div id=\"panel\" class=\"c-t c-r\">\n  <div class=\"phead\">\n    <h1>Overlay Settings<\/h1>\n    <button class=\"ibtn\" id=\"swap\" title=\"Move to the next corner (or drag the title bar)\">\u2922<\/button>\n    <button class=\"ibtn\" id=\"mini\" title=\"Shrink / expand\">\u2014<\/button>\n    <button class=\"ibtn\" id=\"x\" title=\"Close without saving\">\u2715<\/button>\n  <\/div>\n\n  <div class=\"pbody\">\n    <p class=\"hint\">Changes show live on the chat. Press <b>Save<\/b> to keep them, or \u2715 to undo. Drag the title bar or press \u2922 to move this panel out of the way.<\/p>\n\n    <fieldset>\n      <legend>Channel<\/legend>\n      <div class=\"row\"><label>Twitch channel to read\n        <input type=\"text\" class=\"wide\" id=\"s_channel\" placeholder=\"yourchannelname\" autocomplete=\"off\" spellcheck=\"false\"><\/label><\/div>\n      <p class=\"hint\" style=\"margin:0\">Type your channel and press Enter.<\/p>\n      <div class=\"row\"><label>Demo mode<small>Adds fake chatters for testing \u2014 leave off when streaming<\/small><\/label>\n        <label class=\"switch\"><input type=\"checkbox\" id=\"s_demo\"><span><\/span><\/label><\/div>\n      <p class=\"mode\" id=\"modeNote\"><\/p>\n    <\/fieldset>\n\n    <fieldset>\n      <legend>Theme<\/legend>\n      <div class=\"row\"><label>Theme<\/label>\n        <select id=\"s_theme\">\n          <option value=\"neon\">WizHardz Neon<\/option>\n          <option value=\"clean\">Clean (basic)<\/option>\n          <option value=\"minimal\">Minimal (no boxes)<\/option>\n          <option value=\"bubbles\">Bubbles<\/option>\n          <option value=\"terminal\">Retro Terminal<\/option>\n          <option value=\"8bit\">8-Bit Arcade<\/option>\n        <\/select><\/div>\n      <div class=\"row\"><label>Accent colour<small>Used for alerts, highlights and names when name colours are off<\/small>\n        <div class=\"swatches\" id=\"swatches\"><\/div><\/label><\/div>\n      <div class=\"row\"><label>Custom accent (hex)<\/label><input type=\"text\" id=\"s_accent\" placeholder=\"auto\" autocomplete=\"off\" spellcheck=\"false\"><\/div>\n      <div class=\"row\"><label>Use chatters' name colours<\/label>\n        <label class=\"switch\"><input type=\"checkbox\" id=\"s_namecolors\"><span><\/span><\/label><\/div>\n      <div class=\"row\"><label>Background opacity<\/label><input type=\"range\" id=\"s_bga\" min=\"0\" max=\"100\" step=\"1\"><span class=\"val\" id=\"v_bga\"><\/span><\/div>\n      <div class=\"row\"><label>Size<\/label><input type=\"range\" id=\"s_scale\" min=\"60\" max=\"200\" step=\"5\"><span class=\"val\" id=\"v_scale\"><\/span><\/div>\n      <div class=\"row\"><label>Entry animation<\/label>\n        <select id=\"s_anim\"><option value=\"pop\">Pop<\/option><option value=\"slide\">Slide in<\/option><option value=\"fade\">Fade<\/option><option value=\"none\">None<\/option><\/select><\/div>\n      <div class=\"row\"><label>Wonky tilt on cards<\/label>\n        <label class=\"switch\"><input type=\"checkbox\" id=\"s_tilt\"><span><\/span><\/label><\/div>\n    <\/fieldset>\n\n    <fieldset>\n      <legend>Alignment<\/legend>\n      <div class=\"row\"><label>Horizontal position<\/label>\n        <select id=\"s_align\"><option value=\"left\">Left<\/option><option value=\"center\">Centre<\/option><option value=\"right\">Right<\/option><\/select><\/div>\n      <div class=\"row\"><label>Stack messages from<\/label>\n        <select id=\"s_valign\"><option value=\"bottom\">Bottom<\/option><option value=\"top\">Top<\/option><\/select><\/div>\n      <div class=\"row\"><label>New messages appear<\/label>\n        <select id=\"s_order\"><option value=\"newlast\">Below older ones<\/option><option value=\"newfirst\">Above older ones<\/option><\/select><\/div>\n      <div class=\"row\"><label>Message width<\/label>\n        <select id=\"s_width\"><option value=\"fit\">Fit to message<\/option><option value=\"full\">Full width<\/option><\/select><\/div>\n    <\/fieldset>\n\n    <fieldset>\n      <legend>Badges<\/legend>\n      <div class=\"row\"><label>Badges<small>Real = your actual Twitch badges (sub months, mod, VIP\u2026)<\/small><\/label>\n        <select id=\"s_badges\"><option value=\"real\">Real Twitch badges<\/option><option value=\"tags\">Text tags<\/option><option value=\"off\">Off<\/option><\/select><\/div>\n      <div class=\"row\"><label>\"NEW\" tag for first-time chatters<\/label>\n        <label class=\"switch\"><input type=\"checkbox\" id=\"s_first\"><span><\/span><\/label><\/div>\n    <\/fieldset>\n\n    <fieldset>\n      <legend>Emotes<\/legend>\n      <div class=\"row\"><label>7TV emotes<\/label><label class=\"switch\"><input type=\"checkbox\" id=\"s_7tv\"><span><\/span><\/label><\/div>\n      <div class=\"row\"><label>BetterTTV emotes<\/label><label class=\"switch\"><input type=\"checkbox\" id=\"s_bttv\"><span><\/span><\/label><\/div>\n      <div class=\"row\"><label>FrankerFaceZ emotes<\/label><label class=\"switch\"><input type=\"checkbox\" id=\"s_ffz\"><span><\/span><\/label><\/div>\n      <div class=\"row\"><label>Emote size<\/label><input type=\"range\" id=\"s_emotesize\" min=\"60\" max=\"250\" step=\"5\"><span class=\"val\" id=\"v_emotesize\"><\/span><\/div>\n      <div class=\"row\"><label>Collapse emote spam<small>\"catJAM catJAM catJAM\" shows as one catJAM \u00d73<\/small><\/label><label class=\"switch\"><input type=\"checkbox\" id=\"s_collapse\"><span><\/span><\/label><\/div>\n      <div class=\"row\"><label>Emote combos<small>When several chatters send the same emote, it bursts big on screen<\/small><\/label><label class=\"switch\"><input type=\"checkbox\" id=\"s_combo\"><span><\/span><\/label><\/div>\n      <div class=\"row\"><label>Chatters needed for a combo<\/label><input type=\"number\" id=\"s_combomin\" min=\"2\" max=\"20\"><\/div>\n      <div class=\"btns\"><button type=\"button\" class=\"btn alt\" id=\"testCombo\">Test combo<\/button><\/div>\n    <\/fieldset>\n\n    <fieldset>\n      <legend>Highlight Chatters<\/legend>\n      <div class=\"row\"><label>Highlighted users (comma separated)<small>Regulars, friends or mods get a special frame and a \u2605<\/small>\n        <input type=\"text\" class=\"wide\" id=\"s_regulars\" placeholder=\"name1, name2\" autocomplete=\"off\" spellcheck=\"false\"><\/label><\/div>\n      <div class=\"row\"><label>Also highlight mods &amp; VIPs<\/label><label class=\"switch\"><input type=\"checkbox\" id=\"s_regmods\"><span><\/span><\/label><\/div>\n      <div class=\"row\"><label>Highlight colour (hex)<\/label><input type=\"text\" id=\"s_regcolor\" placeholder=\"#ffd84d\" autocomplete=\"off\" spellcheck=\"false\" style=\"width:86px\"><\/div>\n    <\/fieldset>\n\n    <fieldset>\n      <legend>Sounds<\/legend>\n      <div class=\"row\"><label>Message sound<\/label>\n        <select id=\"s_sound\"><option value=\"off\">Off<\/option><option value=\"blip\">Blip<\/option><option value=\"pop\">Pop<\/option><option value=\"bubble\">Bubble<\/option><option value=\"chime\">Chime<\/option><option value=\"coin\">8-bit coin<\/option><option value=\"custom\">Custom (link below)<\/option><\/select><\/div>\n      <div class=\"row\"><label>Alert &amp; combo sound<\/label>\n        <select id=\"s_alertsound\"><option value=\"off\">Off<\/option><option value=\"fanfare\">8-bit fanfare<\/option><option value=\"powerup\">Power-up<\/option><option value=\"sparkle\">Sparkle<\/option><option value=\"chime\">Chime<\/option><option value=\"coin\">8-bit coin<\/option><option value=\"custom\">Custom (link below)<\/option><\/select><\/div>\n      <div class=\"row\"><label>Volume<\/label><input type=\"range\" id=\"s_volume\" min=\"0\" max=\"100\" step=\"5\"><span class=\"val\" id=\"v_volume\"><\/span><\/div>\n      <div class=\"row\"><label>Custom message sound link\n        <input type=\"text\" class=\"wide\" id=\"s_soundurl\" placeholder=\"https://\u2026/sound.mp3\" autocomplete=\"off\" spellcheck=\"false\"><\/label><\/div>\n      <div class=\"row\"><label>Custom alert sound link\n        <input type=\"text\" class=\"wide\" id=\"s_alertsoundurl\" placeholder=\"https://\u2026/sound.mp3\" autocomplete=\"off\" spellcheck=\"false\"><\/label><\/div>\n      <p class=\"hint\" style=\"margin:6px 0 0\">In OBS, tick \"Control audio via OBS\" on this source so the sounds get their own slider in the audio mixer.<\/p>\n    <\/fieldset>\n\n    <fieldset>\n      <legend>Alerts &amp; Filtering<\/legend>\n      <div class=\"row\"><label>Show subs, gifts, raids &amp; announcements<\/label>\n        <label class=\"switch\"><input type=\"checkbox\" id=\"s_events\"><span><\/span><\/label><\/div>\n      <div class=\"row\"><label>Highlight messages that mention you<\/label>\n        <label class=\"switch\"><input type=\"checkbox\" id=\"s_mentions\"><span><\/span><\/label><\/div>\n      <div class=\"row\"><label>Hide links<small>Shows [link] instead of the address<\/small><\/label>\n        <label class=\"switch\"><input type=\"checkbox\" id=\"s_links\"><span><\/span><\/label><\/div>\n      <div class=\"row\"><label>Hide !commands<small>Keeps game commands like !join off the overlay<\/small><\/label>\n        <label class=\"switch\"><input type=\"checkbox\" id=\"s_hidecmds\"><span><\/span><\/label><\/div>\n      <div class=\"row\"><label>Hidden users (comma separated)\n        <input type=\"text\" class=\"wide\" id=\"s_hide\" autocomplete=\"off\" spellcheck=\"false\"><\/label><\/div>\n    <\/fieldset>\n\n    <fieldset>\n      <legend>Timing<\/legend>\n      <div class=\"row\"><label>Messages disappear after (seconds)<small>0 = stay until pushed off<\/small><\/label>\n        <input type=\"number\" id=\"s_fade\" min=\"0\" max=\"600\"><\/div>\n      <div class=\"row\"><label>Max messages on screen<\/label><input type=\"number\" id=\"s_max\" min=\"1\" max=\"50\"><\/div>\n    <\/fieldset>\n\n    <fieldset>\n      <legend>Link with these settings<\/legend>\n      <small style=\"color:#a993cf\">Optional: paste into another Browser Source's URL box to copy this setup.<\/small>\n      <div class=\"linkrow\"><textarea id=\"linkbox\" readonly><\/textarea><button type=\"button\" class=\"btn\" id=\"copyLink\">Copy<\/button><\/div>\n    <\/fieldset>\n    <p class=\"note\" id=\"urlNote\"><\/p>\n  <\/div>\n\n  <div class=\"pfoot\">\n    <button class=\"btn\" id=\"save\">Save<\/button>\n    <button class=\"btn alt\" id=\"test\">Test message<\/button>\n    <button class=\"btn alt\" id=\"cancel\">Cancel<\/button>\n    <button class=\"btn warn\" id=\"reset\">Reset<\/button>\n  <\/div>\n<\/div>\n\n<script>\n(() => {\n  // ================= settings =================\n  const DEFAULTS = {\n    channel: '', demo: false,\n    theme: 'neon', accent: '', namecolors: true, bga: 86, scale: 100, anim: 'pop', tilt: true,\n    align: 'left', valign: 'bottom', order: 'newlast', width: 'fit',\n    badges: 'real', first: true, '7tv': true, bttv: true, ffz: true,\n    events: true, mentions: true, links: true, hidecmds: false,\n    hide: 'nightbot,streamelements,streamlabs,moobot,fossabot',\n    fade: 30, max: 12,\n    emotesize: 100, collapse: true, combo: true, combomin: 3,\n    regulars: '', regmods: false, regcolor: '#ffd84d',\n    sound: 'off', alertsound: 'off', volume: 50, soundurl: '', alertsoundurl: ''\n  };\n  const THEMES = {\n    neon:     { bga: 86, tilt: true },\n    clean:    { bga: 82, tilt: false },\n    minimal:  { bga: 0,  tilt: false },\n    bubbles:  { bga: 95, tilt: false },\n    terminal: { bga: 88, tilt: false },\n    '8bit':   { bga: 94, tilt: false }\n  };\n  const KEY = 'wizhardz-chat-overlay';\n  const store = {\n    get() { try { return JSON.parse(localStorage.getItem(KEY) || '{}'); } catch { return {}; } },\n    set(v) { try { localStorage.setItem(KEY, JSON.stringify(v)); return true; } catch { return false; } },\n    clear() { try { localStorage.removeItem(KEY); } catch {} }\n  };\n  // settings saved by the older version used \"side\" and a 1.0-style scale\n  function migrate(o) {\n    if (o.side && !o.align) o.align = o.side;\n    delete o.side;\n    if (o.scale !== undefined && Number(o.scale) > 0 && Number(o.scale) <= 3) o.scale = Math.round(Number(o.scale) * 100);\n    return o;\n  }\n  const norm = c => String(c || '').toLowerCase().trim()\n    .replace(/^https?:\\/\\/(www\\.)?twitch\\.tv\\//, '').replace(/^[#@]/, '').split(/[/?\\s]/)[0];\n\n  const params = new URLSearchParams(location.search);\n  const urlOverrides = {};\n  for (const [k, v] of params) {\n    if (k === 'side') { urlOverrides.side = v; continue; }\n    if (!(k in DEFAULTS)) continue;\n    urlOverrides[k] = typeof DEFAULTS[k] === 'boolean' ? (v === '1' || v === 'true') :\n                      typeof DEFAULTS[k] === 'number' ? Number(v) : v;\n  }\n  migrate(urlOverrides);\n\n  let saved = { ...DEFAULTS, ...migrate(store.get()) };\n  const computeS = () => {\n    const s = { ...saved, ...urlOverrides };\n    s.channel = norm(s.channel);\n    if (!THEMES[s.theme]) s.theme = 'neon';\n    return s;\n  };\n  let S = computeS();\n\n  const $ = id => document.getElementById(id);\n  const chatEl = $('chat'), statusEl = $('status'), panel = $('panel');\n  let hideUsers = new Set(), regSet = new Set();\n\n  function applyLook() {\n    const b = document.body;\n    b.className = [\n      'theme-' + S.theme, 'a-' + S.align, 'v-' + S.valign, 'o-' + S.order, 'w-' + S.width, 'anim-' + S.anim,\n      S.tilt ? 'tilt' : '', S.namecolors ? 'usercols' : ''\n    ].join(' ');\n    b.style.setProperty('--scale', Math.max(0.4, (Number(S.scale) || 100) / 100));\n    b.style.setProperty('--bga', Math.min(1, Math.max(0, (Number(S.bga) || 0) / 100)));\n    if (/^#[0-9a-f]{6}$/i.test(S.accent)) b.style.setProperty('--accent', S.accent);\n    else b.style.removeProperty('--accent');\n    hideUsers = new Set(String(S.hide).toLowerCase().split(',').map(s => s.trim()).filter(Boolean));\n    regSet = new Set(String(S.regulars).toLowerCase().split(',').map(s => s.trim().replace(/^@/, '')).filter(Boolean));\n    b.style.setProperty('--escale', Math.max(0.3, (Number(S.emotesize) || 100) / 100));\n    b.style.setProperty('--reg', /^#[0-9a-f]{6}$/i.test(S.regcolor) ? S.regcolor : '#ffd84d');\n    trim();\n  }\n\n  // ================= status =================\n  const setStatus = (t, hideAfter) => {\n    statusEl.textContent = t; statusEl.classList.remove('hide');\n    clearTimeout(setStatus.t);\n    if (hideAfter) setStatus.t = setTimeout(() => statusEl.classList.add('hide'), hideAfter);\n  };\n\n  // ================= colours / text =================\n  const FALLBACK = ['#2ff3ff', '#b14dff', '#ff4fd8', '#3dff8a', '#ffe14d', '#ff8a3d', '#8ab4ff'];\n  const colorFor = (name, given) => {\n    if (given) return brighten(given);\n    let h = 0; for (const c of String(name)) h = (h * 31 + c.charCodeAt(0)) >>> 0;\n    return FALLBACK[h % FALLBACK.length];\n  };\n  function brighten(hex) {\n    const m = /^#?([0-9a-f]{6})$/i.exec(hex); if (!m) return '#2ff3ff';\n    let n = parseInt(m[1], 16), r = n >> 16, g = (n >> 8) & 255, b = n & 255;\n    const lum = 0.299 * r + 0.587 * g + 0.114 * b;\n    if (lum < 110) { const k = 110 / Math.max(lum, 1); const mix = c => Math.min(255, Math.round(c * k + 60)); r = mix(r); g = mix(g); b = mix(b); }\n    return `rgb(${r},${g},${b})`;\n  }\n  const esc = s => String(s).replace(/[&<>\"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c]));\n\n  // ================= badges (real images via ivr.fi, no login) =================\n  const badgeMap = {};\n  let badgesLoading = null;\n  function addBadges(list) {\n    if (!Array.isArray(list)) return;\n    for (const set of list) {\n      const id = set.set_id || set.setID || set.id; if (!id) continue;\n      badgeMap[id] = badgeMap[id] || {};\n      for (const v of set.versions || []) {\n        const url = v.image_url_2x || v.image_url_4x || v.image_url_1x;\n        if (url) badgeMap[id][v.id] = { url, title: v.title || id };\n      }\n    }\n  }\n  const getJSON = u => fetch(u).then(r => r.ok ? r.json() : null).catch(() => null);\n  function loadBadges() {\n    if (badgesLoading) return badgesLoading;\n    badgesLoading = (async () => {\n      addBadges(await getJSON('https://api.ivr.fi/v2/twitch/badges/global'));\n      const chan = S.channel;\n      if (chan) addBadges(await getJSON('https://api.ivr.fi/v2/twitch/badges/channel?login=' + encodeURIComponent(chan)));\n    })();\n    return badgesLoading;\n  }\n\n  // ================= 7TV / BTTV / FFZ emotes =================\n  let extEmotes = new Map(), roomId = null, emoteGen = 0;\n  async function loadExtEmotes() {\n    const gen = ++emoteGen;\n    const fix = u => u && (u.startsWith('//') ? 'https:' + u : u);\n    const ffz = new Map(), bttv = new Map(), seven = new Map();\n    const jobs = [];\n\n    if (S.ffz) jobs.push((async () => {\n      const add = j => { for (const set of Object.values(j?.sets || {})) for (const e of set.emoticons || []) {\n        const urls = e.animated || e.urls; const url = fix(urls?.['2'] || urls?.['1']); if (url) ffz.set(e.name, url); } };\n      add(await getJSON('https://api.frankerfacez.com/v1/set/global'));\n      if (roomId) add(await getJSON('https://api.frankerfacez.com/v1/room/id/' + roomId));\n    })());\n    if (S.bttv) jobs.push((async () => {\n      const add = list => { for (const e of list || []) bttv.set(e.code, `https://cdn.betterttv.net/emote/${e.id}/2x`); };\n      add(await getJSON('https://api.betterttv.net/3/cached/emotes/global'));\n      if (roomId) { const j = await getJSON('https://api.betterttv.net/3/cached/users/twitch/' + roomId); add(j?.channelEmotes); add(j?.sharedEmotes); }\n    })());\n    if (S['7tv']) jobs.push((async () => {\n      const add = list => { for (const e of list || []) { const host = e.data?.host; if (!host?.url) continue;\n        const file = (host.files || []).find(f => f.name === '2x.webp') || (host.files || [])[0];\n        seven.set(e.name, fix(host.url) + '/' + (file ? file.name : '2x.webp')); } };\n      add((await getJSON('https://7tv.io/v3/emote-sets/global'))?.emotes);\n      if (roomId) add((await getJSON('https://7tv.io/v3/users/twitch/' + roomId))?.emote_set?.emotes);\n    })());\n\n    await Promise.all(jobs);\n    if (gen === emoteGen) extEmotes = new Map([...ffz, ...bttv, ...seven]); // 7TV wins name clashes\n  }\n\n  // ================= message rendering =================\n  const LINK = /^(https?:\\/\\/\\S+|www\\.\\S+|[\\w-]+(\\.[\\w-]+)*\\.(com|net|org|tv|gg|io|co|uk|ly|me|app|dev|xyz|be|link)(\\/\\S*)?)$/i;\n  // Text is split into parts (text / space / emote) so repeated emotes can be collapsed and counted\n  function wordParts(str, parts) {\n    for (const tok of str.split(/(\\s+)/)) {\n      if (!tok) continue;\n      if (/^\\s+$/.test(tok)) { parts.push({ t: 'ws', h: tok }); continue; }\n      const ext = extEmotes.get(tok);\n      if (ext) { parts.push({ t: 'em', k: ext, n: tok, h: `<img class=\"emote\" alt=\"${esc(tok)}\" src=\"${esc(ext)}\">` }); continue; }\n      if (S.links && LINK.test(tok)) { parts.push({ t: 'tx', h: '<span class=\"link\">[link]<\/span>' }); continue; }\n      if (/^@[A-Za-z0-9_]{2,25}[,.!?]?$/.test(tok)) { parts.push({ t: 'tx', h: `<span class=\"mention\">${esc(tok)}<\/span>` }); continue; }\n      parts.push({ t: 'tx', h: esc(tok) });\n    }\n  }\n  function renderText(text, emotesTag) {\n    const chars = Array.from(text || ''), ranges = [], parts = [];\n    if (emotesTag) {\n      for (const part of emotesTag.split('/')) {\n        const [id, pos] = part.split(':'); if (!pos) continue;\n        for (const r of pos.split(',')) { const [a, b] = r.split('-').map(Number); ranges.push({ a, b, id }); }\n      }\n      ranges.sort((x, y) => x.a - y.a);\n    }\n    let i = 0;\n    for (const r of ranges) {\n      if (r.a < i) continue;\n      wordParts(chars.slice(i, r.a).join(''), parts);\n      const name = chars.slice(r.a, r.b + 1).join('');\n      const url = `https://static-cdn.jtvnw.net/emoticons/v2/${encodeURIComponent(r.id)}/default/dark/2.0`;\n      parts.push({ t: 'em', k: url, n: name, h: `<img class=\"emote\" alt=\"${esc(name)}\" src=\"${url}\">` });\n      i = r.b + 1;\n    }\n    wordParts(chars.slice(i).join(''), parts);\n\n    let list = parts;\n    if (S.collapse) {\n      list = [];\n      for (const p of parts) {\n        if (p.t === 'em') {\n          let j = list.length - 1;\n          while (j >= 0 && list[j].t === 'ws') j--;\n          if (j >= 0 && list[j].t === 'em' && list[j].k === p.k) { list[j].c = (list[j].c || 1) + 1; list.length = j + 1; continue; }\n          list.push({ ...p });\n        } else list.push(p);\n      }\n    }\n    const html = list.map(p => p.t === 'em' && p.c > 1 ? p.h + `<span class=\"ecount\">\u00d7${p.c}<\/span>` : p.h).join('');\n    const emoteOnly = list.some(p => p.t === 'em') && list.every(p => p.t !== 'tx');\n    const emotes = [...new Map(parts.filter(p => p.t === 'em').map(p => [p.k, { k: p.k, n: p.n }])).values()];\n    return { html, emoteOnly, emotes };\n  }\n  function badgeHtml(badges, first) {\n    let h = '';\n    if (first && S.first) h += '<span class=\"chip first\">NEW<\/span>';\n    if (S.badges === 'off' || !badges) return h;\n    if (S.badges === 'real') {\n      for (const pair of badges.split(',')) {\n        const [set, ver] = pair.split('/');\n        const b = badgeMap[set]?.[ver];\n        if (b) h += `<img class=\"badge\" alt=\"${esc(b.title)}\" src=\"${esc(b.url)}\">`;\n      }\n      return h;\n    }\n    if (badges.includes('broadcaster/')) h += '<span class=\"chip host\">HOST<\/span>';\n    if (badges.includes('moderator/')) h += '<span class=\"chip mod\">MOD<\/span>';\n    if (badges.includes('vip/')) h += '<span class=\"chip vip\">VIP<\/span>';\n    if (badges.includes('subscriber/') || badges.includes('founder/')) h += '<span class=\"chip sub\">SUB<\/span>';\n    return h;\n  }\n  const mentionsMe = text => !!S.channel && new RegExp('(^|[^\\\\w])@?' + S.channel + '([^\\\\w]|$)', 'i').test(text);\n\n  // Each card keeps its original chat data, so settings changes can redraw cards already on screen\n  const EV_ICON = { sub: '\u2b50', resub: '\u2b50', giftpaidupgrade: '\u2b50', primepaidupgrade: '\u2b50', subgift: '\ud83c\udf81', submysterygift: '\ud83c\udf81', raid: '\ud83d\ude80', announcement: '\ud83d\udce3', bitsbadgetier: '\ud83d\udc8e' };\n  const loginOf = d => (d.login || d.name || '').toLowerCase();\n  function allowed(d) {\n    if (hideUsers.has(loginOf(d))) return false;\n    if (d.kind === 'event') return S.events;\n    if (S.hidecmds && d.text.trim().startsWith('!')) return false;\n    return true;\n  }\n  function build(el, d) {\n    const login = loginOf(d);\n    el.dataset.user = login;\n    if (d.id) el.dataset.id = d.id;\n    if (d.kind === 'event') {\n      el.className = 'msg event';\n      const line = d.type === 'announcement' ? `Announcement from ${d.name}` : (d.system || d.name);\n      let html = `<div class=\"evline\">${EV_ICON[d.type] || '\u2728'} ${esc(line)}<\/div>`;\n      if (d.text) html += `<div class=\"text\">${renderText(d.text, d.emotes).html}<\/div>`;\n      el.innerHTML = html;\n      return;\n    }\n    const body = renderText(d.text, d.emotes);\n    const cls = ['msg'];\n    if (d.action) cls.push('action');\n    if (d.first && S.first) cls.push('first');\n    if (d.highlight || (S.mentions && login !== S.channel && mentionsMe(d.text))) cls.push('hl');\n    if (regSet.has(login) || (S.regmods && /(^|,)(moderator|vip|broadcaster)\\//.test(d.badges || ''))) cls.push('reg');\n    if (body.emoteOnly) cls.push('emote-only');\n    el.className = cls.join(' ');\n    el.style.setProperty('--user-col', colorFor(d.name, d.color));\n    let chips = badgeHtml(d.badges, d.first);\n    if (d.bits) chips += `<span class=\"chip bits\">\ud83d\udc8e ${esc(d.bits)}<\/span>`;\n    el.innerHTML = `<div class=\"head\">${chips}<span class=\"name\">${esc(d.name)}<\/span><\/div><div class=\"text\">${body.html}<\/div>`;\n  }\n  function addCard(d) {\n    if (!allowed(d)) return;\n    const el = document.createElement('div');\n    el._d = d;\n    build(el, d);\n    push(el);\n    playSound(d.kind === 'event');\n    if (d.kind === 'msg' && S.combo) comboTrack(loginOf(d), renderText(d.text, d.emotes).emotes);\n  }\n\n  // ================= emote combos =================\n  const combos = new Map(); // emote url -> { users: Map(login -> time), el, timer }\n  const COMBO_WINDOW = 8000;\n  function comboTrack(login, emotes) {\n    const now = Date.now();\n    for (const e of emotes) {\n      let c = combos.get(e.k);\n      if (!c) { c = { users: new Map(), url: e.k, name: e.n }; combos.set(e.k, c); }\n      for (const [u, t] of c.users) if (now - t > COMBO_WINDOW) c.users.delete(u);\n      c.users.set(login, now);\n      if (c.users.size >= Math.max(2, Number(S.combomin) || 3)) showCombo(c);\n    }\n  }\n  function showCombo(c) {\n    const n = c.users.size;\n    if (!c.el || !c.el.isConnected || c.el.classList.contains('bye')) {\n      const el = document.createElement('div');\n      el.className = 'combo';\n      el.style.left = (30 + Math.random() * 40) + '%';\n      el.style.top = (30 + Math.random() * 25) + '%';\n      el.innerHTML = `<img alt=\"${esc(c.name)}\" src=\"${esc(c.url)}\"><div class=\"ccount\"><\/div>`;\n      $('fx').appendChild(el);\n      c.el = el;\n      playSound(true);\n    } else {\n      c.el.classList.remove('bump'); void c.el.offsetWidth; c.el.classList.add('bump');\n    }\n    c.el.querySelector('.ccount').textContent = `\u00d7${n} COMBO`;\n    clearTimeout(c.timer);\n    const el = c.el;\n    c.timer = setTimeout(() => { el.classList.add('bye'); setTimeout(() => el.remove(), 600); }, 3500);\n  }\n\n  // ================= sounds (made in the browser, no files needed) =================\n  let actx = null, lastMsgSound = 0;\n  const NOTES = {\n    blip:    [[880, 0, .07, 'square']],\n    chime:   [[1046.5, 0, .4, 'sine'], [1568, .08, .5, 'sine']],\n    coin:    [[988, 0, .08, 'square'], [1319, .08, .4, 'square']],\n    fanfare: [[523, 0, .12, 'square'], [659, .12, .12, 'square'], [784, .24, .12, 'square'], [1047, .36, .55, 'square']],\n    powerup: [392, 494, 587, 784, 988, 1175, 1568].map((f, i) => [f, i * .055, .09, 'triangle']),\n    sparkle: [[1568, 0, .18, 'sine'], [2093, .07, .22, 'sine'], [2637, .14, .45, 'sine']]\n  };\n  const SWEEPS = { pop: [700, 160, .09, 'sine'], bubble: [300, 950, .12, 'sine'] };\n  function playSound(isAlert, force) {\n    const name = isAlert ? S.alertsound : S.sound;\n    if (!name || name === 'off') return;\n    const vol = Math.max(0, Math.min(1, (Number(S.volume) || 0) / 100));\n    if (!vol) return;\n    const now = performance.now();\n    if (!isAlert && !force && now - lastMsgSound < 120) return; // don't machine-gun during busy chat\n    if (!isAlert) lastMsgSound = now;\n    if (name === 'custom') {\n      const url = isAlert ? S.alertsoundurl : S.soundurl;\n      if (!url) return;\n      try { const a = new Audio(url); a.volume = vol; a.play().catch(() => {}); } catch {}\n      return;\n    }\n    try {\n      actx = actx || new (window.AudioContext || window.webkitAudioContext)();\n      if (actx.state === 'suspended') actx.resume();\n      const t0 = actx.currentTime + .01;\n      const tone = (f, f2, start, dur, type) => {\n        const o = actx.createOscillator(), g = actx.createGain();\n        const peak = vol * (type === 'square' ? .12 : type === 'triangle' ? .25 : .3);\n        o.type = type;\n        o.frequency.setValueAtTime(f, t0 + start);\n        if (f2) o.frequency.exponentialRampToValueAtTime(f2, t0 + start + dur);\n        g.gain.setValueAtTime(0.0001, t0 + start);\n        g.gain.linearRampToValueAtTime(peak, t0 + start + .005);\n        g.gain.exponentialRampToValueAtTime(0.0001, t0 + start + dur);\n        o.connect(g).connect(actx.destination);\n        o.start(t0 + start); o.stop(t0 + start + dur + .02);\n      };\n      if (SWEEPS[name]) { const [a, b, d, ty] = SWEEPS[name]; tone(a, b, 0, d, ty); }\n      else for (const [f, st, d, ty] of NOTES[name] || []) tone(f, 0, st, d, ty);\n    } catch {}\n  }\n  const addMessage = m => addCard({ ...m, kind: 'msg' });\n  const addEvent = e => addCard({ ...e, kind: 'event' });\n  function redrawAll() {\n    for (const el of [...chatEl.children]) {\n      if (!el._d || el.classList.contains('out')) continue;\n      el.hidden = !allowed(el._d); // hidden rather than deleted, so Cancel can bring them back\n      if (el.hidden) continue;\n      build(el, el._d);\n      el.querySelectorAll('img').forEach(i => i.addEventListener('load', trim, { once: true }));\n    }\n    trim();\n  }\n\n  function push(el) {\n    chatEl.appendChild(el);\n    el.querySelectorAll('img').forEach(i => i.addEventListener('load', trim, { once: true }));\n    trim();\n    if (S.fade > 0) setTimeout(() => removeEl(el), S.fade * 1000);\n  }\n  function removeEl(el) {\n    if (!el.isConnected || el.classList.contains('out')) return;\n    el.classList.add('out');\n    setTimeout(() => el.remove(), 450);\n  }\n  // keep within the max count, and drop the oldest if they no longer fit on screen\n  function overflowing() {\n    const h = chatEl.clientHeight;\n    for (const c of chatEl.children) if (c.offsetTop < 0 || c.offsetTop + c.offsetHeight > h) return true;\n    return false;\n  }\n  function trim() {\n    const max = Math.max(1, Number(S.max) || 12);\n    while (chatEl.children.length > max) chatEl.firstElementChild.remove();\n    let guard = 60;\n    while (chatEl.children.length > 1 && overflowing() && guard--) chatEl.firstElementChild.remove();\n  }\n\n  // ================= Twitch IRC (read-only, no login) =================\n  function parseTags(raw) {\n    const t = {};\n    for (const kv of raw.split(';')) {\n      const i = kv.indexOf('=');\n      t[kv.slice(0, i)] = kv.slice(i + 1).replace(/\\\\s/g, ' ').replace(/\\\\:/g, ';').replace(/\\\\\\\\/g, '\\\\');\n    }\n    return t;\n  }\n  let ws = null, retry = 1000, retryTimer = null, liveState = 'off';\n  const running = { channel: '', demo: false };\n  function connect() {\n    const chan = running.channel;\n    if (!chan) return;\n    liveState = 'connecting'; updateMode();\n    setStatus(`connecting to #${chan}\u2026`);\n    const sock = new WebSocket('wss://irc-ws.chat.twitch.tv:443');\n    ws = sock;\n    sock.onopen = () => {\n      sock.send('CAP REQ :twitch.tv/tags twitch.tv/commands');\n      sock.send('PASS SCHMOOPIIE');\n      sock.send('NICK justinfan' + Math.floor(10000 + Math.random() * 80000));\n      sock.send('JOIN #' + chan);\n    };\n    sock.onmessage = e => { if (ws === sock) for (const line of e.data.split('\\r\\n')) if (line) handle(line); };\n    sock.onclose = () => {\n      if (ws !== sock) return; // replaced by a newer connection\n      liveState = 'retrying'; updateMode();\n      setStatus('disconnected \u2014 retrying\u2026');\n      retryTimer = setTimeout(connect, retry);\n      retry = Math.min(retry * 2, 30000);\n    };\n  }\n  function disconnect() {\n    clearTimeout(retryTimer);\n    const sock = ws; ws = null; roomId = null; liveState = 'off';\n    if (sock) try { sock.close(); } catch {}\n  }\n  function handle(line) {\n    if (line.startsWith('PING')) { ws.send('PONG :tmi.twitch.tv'); return; }\n    let tags = {}, rest = line;\n    if (rest[0] === '@') { const sp = rest.indexOf(' '); tags = parseTags(rest.slice(1, sp)); rest = rest.slice(sp + 1); }\n    const m = /^:(\\S+)\\s+(\\S+)\\s+#?(\\S+)(?:\\s+:(.*))?$/.exec(rest);\n    if (!m) return;\n    const [, prefix, cmd, , trailing = ''] = m;\n\n    if (cmd === 'ROOMSTATE' && tags['room-id'] && !roomId) {\n      roomId = tags['room-id'];\n      retry = 1000;\n      liveState = 'live'; updateMode();\n      setStatus(`connected to #${running.channel} \u2014 loading emotes\u2026`);\n      loadExtEmotes().then(() => { setStatus(`connected to #${running.channel} \u2713`, 3000); redrawAll(); });\n      return;\n    }\n    if (cmd === 'PRIVMSG') {\n      const login = prefix.split('!')[0];\n      let text = trailing, action = false;\n      const am = /^\\u0001ACTION (.*)\\u0001$/.exec(text);\n      if (am) { text = am[1]; action = true; }\n      addMessage({ id: tags.id, login, name: tags['display-name'] || login, color: tags.color,\n        badges: tags.badges, emotes: tags.emotes, first: tags['first-msg'] === '1',\n        highlight: tags['msg-id'] === 'highlighted-message', bits: tags.bits, text, action });\n    } else if (cmd === 'USERNOTICE') {\n      const type = tags['msg-id'];\n      if (type === 'subgift' && tags['msg-param-community-gift-id']) return; // part of a mass gift \u2014 already announced\n      if (!EV_ICON[type] && !tags['system-msg']) return;\n      addEvent({ type, id: tags.id, login: tags.login, name: tags['display-name'] || tags.login,\n        system: tags['system-msg'], text: trailing, emotes: tags.emotes });\n    } else if (cmd === 'CLEARCHAT') {\n      if (trailing) chatEl.querySelectorAll(`.msg[data-user=\"${CSS.escape(trailing.toLowerCase())}\"]`).forEach(removeEl);\n      else [...chatEl.children].forEach(removeEl);\n    } else if (cmd === 'CLEARMSG') {\n      const id = tags['target-msg-id'];\n      if (id) chatEl.querySelectorAll(`.msg[data-id=\"${CSS.escape(id)}\"]`).forEach(removeEl);\n    } else if (cmd === 'NOTICE' && /does not exist|suspended/i.test(trailing)) {\n      liveState = 'bad'; updateMode();\n      setStatus(`#${running.channel}: ${trailing}`);\n    }\n  }\n\n  // ================= samples (demo + test button) =================\n  const PEOPLE = [\n    ['SparkleGoblin', '#ff4fd8', 'subscriber/12'],\n    ['moddy_mcmodface', '#3dff8a', 'moderator/1,subscriber/24'],\n    ['FrostbiteFred', '#2ff3ff', 'premium/1'],\n    ['xX_Pyro_Xx', '#ff8a3d', 'vip/1'],\n    ['quiet_lurker', '', ''],\n    ['NewbieNell', '#ffe14d', '']\n  ];\n  const LINES = [\n    'that fireball was CRIMINAL \ud83d\udd25', 'who let the necromancer cook', 'gg everyone', '!join',\n    '@SparkleGoblin you got absolutely zapped', 'first time here, this game is wild',\n    'my wizard has no arms and no fear', 'one more round PLEASE', 'Kappa', 'catJAM catJAM', 'OMEGALUL',\n    '@{me} that was the best round yet'\n  ];\n  const EVENTS = [\n    { type: 'resub', name: 'SparkleGoblin', system: \"SparkleGoblin subscribed at Tier 1. They've subscribed for 6 months!\", text: 'love this game' },\n    { type: 'raid', name: 'BigWizardEnergy', system: '12 raiders from BigWizardEnergy have joined!' },\n    { type: 'submysterygift', name: 'xX_Pyro_Xx', system: 'xX_Pyro_Xx is gifting 5 Tier 1 Subs to the community!' },\n    { type: 'announcement', name: 'moddy_mcmodface', text: 'Next round starts in 2 minutes \u2014 type !join' }\n  ];\n  let sampleN = 0;\n  function sample(forceEvent) {\n    const n = sampleN++;\n    if (forceEvent || (n > 0 && n % 8 === 0)) {\n      const e = EVENTS[Math.floor(n / 8) % EVENTS.length];\n      addEvent({ ...e, login: e.name.toLowerCase() });\n      return;\n    }\n    const [name, color, badges] = PEOPLE[n % PEOPLE.length];\n    const text = LINES[(n * 5) % LINES.length].replace('{me}', S.channel || 'streamer');\n    addMessage({ name, login: name.toLowerCase(), color, badges,\n      emotes: text === 'Kappa' ? '25:0-4' : '', first: name === 'NewbieNell' && n < 7,\n      action: n % 11 === 9, bits: n % 13 === 5 ? '100' : '', text });\n  }\n  let demoTimer = null;\n  function startDemo() {\n    const tick = () => { sample(); demoTimer = setTimeout(tick, 1400 + Math.random() * 1800); };\n    tick();\n  }\n  function stopDemo() { clearTimeout(demoTimer); demoTimer = null; }\n\n  // Live chat runs when a channel is set; fake chatters only run when Demo mode is switched on\n  function applyMode() {\n    const chanChanged = running.channel !== S.channel;\n    stopDemo();\n    if (chanChanged || !S.channel) disconnect();\n    running.channel = S.channel;\n    running.demo = S.demo;\n    if (chanChanged) {\n      badgesLoading = null;\n      if (S.badges === 'real') loadBadges().then(redrawAll);\n      if (!S.channel) loadExtEmotes(); // global emotes only\n    }\n    if (S.channel && !ws) connect();\n    if (S.demo) startDemo();\n    if (!S.channel && !S.demo) setStatus('no channel set \u2014 hover over the overlay and click \u2699', 10000);\n    else if (!S.channel) setStatus('demo mode (fake chatters)', 4000);\n    updateMode();\n  }\n  function updateMode() {\n    const el = $('modeNote');\n    if (!el) return;\n    const live = running.channel\n      ? ({ connecting: `Connecting to #${running.channel}\u2026`, live: `Reading #${running.channel} \u2713`,\n           retrying: `Reconnecting to #${running.channel}\u2026`, bad: `#${running.channel} not found \u2014 check the spelling` }[liveState] || `#${running.channel}`)\n      : 'No channel set';\n    el.textContent = live + (running.demo ? ' \u00b7 demo chatters ON' : '');\n    el.dataset.state = running.channel ? liveState : 'none';\n  }\n\n  // ================= settings panel =================\n  const FIELDS = Object.keys(DEFAULTS);\n  const SWATCHES = ['', '#2ff3ff', '#b14dff', '#ff4fd8', '#3dff8a', '#ffe14d', '#ff8a3d', '#ff4d5e', '#8b7bff', '#ffffff'];\n  const swBox = $('swatches');\n  for (const c of SWATCHES) {\n    const b = document.createElement('button');\n    b.type = 'button'; b.className = 'sw' + (c ? '' : ' def'); b.dataset.c = c;\n    b.title = c || 'Theme default';\n    if (c) b.style.background = c;\n    b.onclick = () => { $('s_accent').value = c; $('s_accent').dispatchEvent(new Event('input', { bubbles: true })); };\n    swBox.appendChild(b);\n  }\n  function updateExtras() {\n    for (const b of swBox.children) b.classList.toggle('sel', (b.dataset.c || '') === (S.accent || ''));\n    $('v_bga').textContent = S.bga + '%';\n    $('v_scale').textContent = S.scale + '%';\n    $('v_volume').textContent = S.volume + '%';\n    $('v_emotesize').textContent = S.emotesize + '%';\n    const q = new URLSearchParams();\n    for (const f of FIELDS) if (S[f] !== DEFAULTS[f]) q.set(f, typeof S[f] === 'boolean' ? (S[f] ? '1' : '0') : S[f]);\n    $('linkbox').value = location.href.split(/[?#]/)[0] + (q.toString() ? '?' + q : '');\n  }\n  function fillPanel() {\n    for (const f of FIELDS) {\n      const el = $('s_' + f); if (!el) continue;\n      if (el.type === 'checkbox') el.checked = !!S[f]; else el.value = S[f];\n    }\n    const keys = Object.keys(urlOverrides);\n    $('urlNote').textContent = keys.length\n      ? `Heads up: this source's URL has settings in it (${keys.join(', ')}). Those win after a reload \u2014 remove them from the URL to use this menu.`\n      : '';\n    updateExtras();\n    updateMode();\n  }\n  function readPanel() {\n    const v = {};\n    for (const f of FIELDS) {\n      const el = $('s_' + f);\n      if (!el) { v[f] = S[f]; continue; }\n      v[f] = el.type === 'checkbox' ? el.checked :\n             (el.type === 'number' || el.type === 'range') ? Number(el.value) : el.value.trim();\n    }\n    v.channel = norm(v.channel);\n    const hex = v.accent.replace(/^#/, '');\n    v.accent = /^[0-9a-f]{6}$/i.test(hex) ? '#' + hex.toLowerCase() : '';\n    const rhex = v.regcolor.replace(/^#/, '');\n    v.regcolor = /^[0-9a-f]{6}$/i.test(rhex) ? '#' + rhex.toLowerCase() : DEFAULTS.regcolor;\n    return v;\n  }\n\n  // the panel sits in the corner away from the chat; it can be dragged or cycled round the corners\n  let manualDock = false;\n  const CORNERS = ['tr', 'br', 'bl', 'tl'];\n  const dockFor = () => (S.valign === 'top' ? 'b' : 't') + (S.align === 'right' ? 'l' : 'r');\n  function setDock(c) {\n    panel.style.left = panel.style.top = '';\n    panel.classList.remove('c-t', 'c-b', 'c-l', 'c-r');\n    panel.classList.add('c-' + c[0], 'c-' + c[1]);\n    panel.dataset.corner = c;\n  }\n  panel.querySelector('.phead').addEventListener('pointerdown', e => {\n    if (e.target.closest('button')) return;\n    const r = panel.getBoundingClientRect(), dx = e.clientX - r.left, dy = e.clientY - r.top;\n    panel.classList.remove('c-t', 'c-b', 'c-l', 'c-r');\n    const move = ev => {\n      const x = Math.min(Math.max(0, ev.clientX - dx), innerWidth - panel.offsetWidth);\n      const y = Math.min(Math.max(0, ev.clientY - dy), innerHeight - 40);\n      panel.style.left = x + 'px'; panel.style.top = y + 'px';\n    };\n    move(e);\n    manualDock = true;\n    const up = () => { removeEventListener('pointermove', move); removeEventListener('pointerup', up); };\n    addEventListener('pointermove', move); addEventListener('pointerup', up);\n  });\n\n  panel.addEventListener('input', e => {\n    if (e.target.id === 's_theme') {\n      const p = THEMES[e.target.value];\n      if (p) { $('s_bga').value = p.bga; $('s_tilt').checked = p.tilt; }\n    }\n    const prev = S;\n    S = { ...S, ...readPanel() };\n    applyLook();\n    updateExtras();\n    redrawAll();\n    if (S.badges === 'real') loadBadges().then(redrawAll);\n    if (['7tv', 'bttv', 'ffz'].some(k => prev[k] !== S[k])) loadExtEmotes().then(redrawAll);\n    if (!manualDock && (prev.valign !== S.valign || prev.align !== S.align)) setDock(dockFor());\n    if (S.demo !== running.demo) applyMode();\n    const id = e.target.id;\n    if (id === 's_sound' || id === 's_soundurl') playSound(false, true);\n    if (id === 's_alertsound' || id === 's_alertsoundurl') playSound(true, true);\n    if (id === 's_volume') playSound(S.sound === 'off', true);\n  });\n  $('testCombo').onclick = () => {\n    PEOPLE.slice(0, Math.max(2, Number(S.combomin) || 3) + 1).forEach(([name, color, badges], i) =>\n      setTimeout(() => addMessage({ name, login: name.toLowerCase(), color, badges, emotes: '25:0-4', text: 'Kappa' }), i * 350));\n  };\n  // the channel switches over when you press Enter or click away from the box\n  $('s_channel').addEventListener('change', () => { if (S.channel !== running.channel) applyMode(); });\n  $('s_channel').addEventListener('keydown', e => { if (e.key === 'Enter') e.target.blur(); });\n\n  // clicking a setting's name also flips its switch\n  panel.addEventListener('click', e => {\n    const lab = e.target.closest('.row > label:not(.switch)');\n    if (!lab || e.target.closest('input,select,button,textarea')) return;\n    const cb = lab.parentElement.querySelector('.switch input');\n    if (cb) { cb.checked = !cb.checked; cb.dispatchEvent(new Event('input', { bubbles: true })); }\n  });\n\n  function openPanel() {\n    fillPanel();\n    if (!manualDock) setDock(dockFor());\n    panel.classList.remove('mini');\n    panel.classList.add('open');\n  }\n  function cancelPanel() {\n    const prev = S;\n    S = computeS();\n    applyLook();\n    redrawAll();\n    if (['7tv', 'bttv', 'ffz'].some(k => prev[k] !== S[k])) loadExtEmotes().then(redrawAll);\n    if (S.channel !== running.channel || S.demo !== running.demo) applyMode();\n    panel.classList.remove('open');\n  }\n  $('gear').onclick = openPanel;\n  $('x').onclick = cancelPanel;\n  $('cancel').onclick = cancelPanel;\n  $('swap').onclick = () => { manualDock = true; setDock(CORNERS[(CORNERS.indexOf(panel.dataset.corner) + 1) % 4]); };\n  $('mini').onclick = () => panel.classList.toggle('mini');\n  $('test').onclick = () => sample(false);\n  $('copyLink').onclick = async () => {\n    const box = $('linkbox'), btn = $('copyLink');\n    let ok = false;\n    try { await navigator.clipboard.writeText(box.value); ok = true; } catch {}\n    if (!ok) { box.focus(); box.select(); try { ok = document.execCommand('copy'); } catch {} }\n    btn.textContent = ok ? 'Copied!' : 'Ctrl+C';\n    if (!ok) { box.focus(); box.select(); } // selected so Ctrl+C works\n    clearTimeout(btn._t);\n    btn._t = setTimeout(() => { btn.textContent = 'Copy'; }, 2000);\n  };\n  $('save').onclick = () => {\n    const v = readPanel();\n    if (!store.set(v)) { $('urlNote').textContent = \"Couldn't save here \u2014 paste the link above into the source's URL box instead.\"; return; }\n    saved = { ...DEFAULTS, ...v };\n    S = { ...S, ...v };\n    if (S.channel !== running.channel || S.demo !== running.demo) applyMode();\n    panel.classList.remove('open');\n    setStatus('settings saved \u2713', 2000);\n  };\n  let resetArmed = false;\n  $('reset').onclick = () => {\n    if (!resetArmed) {\n      resetArmed = true; $('reset').textContent = 'Sure? Click again';\n      setTimeout(() => { resetArmed = false; $('reset').textContent = 'Reset'; }, 3000);\n      return;\n    }\n    store.clear(); location.reload();\n  };\n  document.addEventListener('keydown', e => { if (e.key === 'Escape' && panel.classList.contains('open')) cancelPanel(); });\n\n  // ================= start =================\n  applyLook();\n  const badgeWait = S.badges === 'real'\n    ? Promise.race([loadBadges(), new Promise(r => setTimeout(r, 3000))])\n    : Promise.resolve();\n  badgeWait.then(applyMode);\n})();\n<\/script>\n<\/body>\n<\/html>\n";
  const OKEY = "wizhardz-chat-overlay";
  const frame = $("#ovFrame");
  const ls = {
    get(k, d) { try { const v = localStorage.getItem(k); return v == null ? d : JSON.parse(v); } catch (e) { return d; } },
    set(k, v) { try { localStorage.setItem(k, JSON.stringify(v)); } catch (e) {} }
  };
  const readOv = () => ls.get(OKEY, {}) || {};

  // Start the overlay on the same channel as the rest of TOS HUB, unless it already has one.
  (() => {
    const o = readOv(), ch = (ls.get("streamhub.cfg", {}) || {}).channel;
    if (!o.channel && ch) { o.channel = ch; ls.set(OKEY, o); }
  })();

  // ---------- preview ----------
  // The overlay's own "copy link" box doesn't apply inside the preview, so it's hidden there.
  const previewHtml = OVERLAY_HTML.replace("</head>",
    "<style>fieldset:has(#linkbox),#urlNote{display:none!important}</style></head>");
  let loaded = false;
  const loadPreview = () => { loaded = true; frame.srcdoc = previewHtml; };
  const ensure = () => { if (!loaded) loadPreview(); };
  const inFrame = id => { try { return frame.contentDocument && frame.contentDocument.getElementById(id); } catch (e) { return null; } };
  const clickInFrame = id => {
    if (!loaded) { loadPreview(); frame.addEventListener("load", () => setTimeout(() => { const b = inFrame(id); if (b) b.click(); }, 300), { once: true }); return; }
    const b = inFrame(id); if (b) b.click();
  };
  $("#ovSettings").onclick = () => clickInFrame("gear");
  $("#ovTest").onclick = () => clickInFrame("test");
  $("#ovReload").onclick = loadPreview;

  // ---------- OBS link ----------
  const fileUrl = () => location.protocol === "file:" ? new URL("chat-overlay.html", location.href).href : "";
  function obsLink() {
    const q = new URLSearchParams();
    for (const [k, v] of Object.entries(readOv())) {
      if (k === "demo" || v == null) continue;
      q.set(k, typeof v === "boolean" ? (v ? "1" : "0") : String(v));
    }
    q.set("demo", "0"); // never send fake chatters to the live overlay
    return (fileUrl() || "file:///C:/…/Stream%20Hub/chat-overlay.html") + "?" + q.toString();
  }
  function refreshInfo() {
    $("#ovLink").value = obsLink();
    const f = fileUrl();
    $("#ovWhere").textContent = f
      ? "Overlay file: " + decodeURIComponent(f.replace(/^file:\/\/\/?/, "")).replace(/\//g, "\\")
      : "Open TOS HUB from your desktop app to send the overlay to OBS. This preview can't see the files on your computer.";
    $("#ovUpdate").disabled = $("#ovCreate").disabled = !f;
  }
  window.addEventListener("storage", e => { if (e.key === OKEY) refreshInfo(); });

  const msg = (t, bad) => { const m = $("#ovMsg"); m.textContent = t; m.style.color = bad ? "var(--bad)" : "var(--good)"; };
  const opt = (v, t) => { const o = document.createElement("option"); o.value = v; o.textContent = t; return o; };

  // ---------- OBS browser sources ----------
  const obsReady = () => window.hubObs && window.hubObs.connected;
  async function refreshSources() {
    const sel = $("#ovSource");
    const want = sel.value || ls.get("streamhub.ovSource", "");
    if (!obsReady()) { sel.innerHTML = ""; sel.append(opt("", "Connect OBS on the Connections tab first")); return; }
    try {
      const r = await window.hubObs.request("GetInputList", { inputKind: "browser_source" });
      const names = (r.inputs || []).map(i => i.inputName).sort((a, b) => a.localeCompare(b));
      sel.innerHTML = "";
      if (!names.length) sel.append(opt("", "No browser sources yet. Use “Create a new one”"));
      names.forEach(n => sel.append(opt(n, n)));
      if (names.includes(want)) sel.value = want;
      else { const g = names.find(n => /chat/i.test(n)); if (g) sel.value = g; }
    } catch (e) { msg("Couldn't list OBS sources: " + e.message, true); }
  }
  $("#ovSource").onchange = () => ls.set("streamhub.ovSource", $("#ovSource").value);
  let wasReady = null;
  setInterval(() => { const r = !!obsReady(); if (r !== wasReady) { wasReady = r; refreshSources(); } }, 1500);

  function canSend() {
    if (!fileUrl()) { msg("Open TOS HUB from your desktop app first, so it knows where the overlay file is.", true); return false; }
    if (!obsReady()) { msg("Connect to OBS on the Connections tab first.", true); return false; }
    return true;
  }
  $("#ovUpdate").onclick = async () => {
    if (!canSend()) return;
    const name = $("#ovSource").value;
    if (!name) { msg("Pick a browser source, or click “Create a new one”.", true); return; }
    try {
      await window.hubObs.request("SetInputSettings", { inputName: name, inputSettings: { is_local_file: false, url: obsLink() }, overlay: true });
      ls.set("streamhub.ovSource", name);
      msg(`Updated “${name}” in OBS ✓`);
    } catch (e) { msg("OBS said: " + e.message, true); }
  };
  $("#ovCreate").onclick = async () => {
    if (!canSend()) return;
    const obs = window.hubObs;
    try {
      let scene = obs.current;
      if (!scene) { const c = await obs.request("GetCurrentProgramScene"); scene = c.currentProgramSceneName || c.sceneName; }
      const all = await obs.request("GetInputList");
      const taken = new Set((all.inputs || []).map(i => i.inputName));
      let name = "WizHardz Chat", n = 2;
      while (taken.has(name)) name = `WizHardz Chat ${n++}`;
      await obs.request("CreateInput", {
        sceneName: scene, inputName: name, inputKind: "browser_source", sceneItemEnabled: true,
        inputSettings: { is_local_file: false, url: obsLink(), width: 600, height: 1000, reroute_audio: true }
      });
      ls.set("streamhub.ovSource", name);
      await refreshSources();
      $("#ovSource").value = name;
      msg(`Added “${name}” to the “${scene}” scene ✓ Drag it into place in OBS.`);
    } catch (e) { msg("OBS said: " + e.message, true); }
  };

  // ---------- copy / save ----------
  $("#ovCopy").onclick = async () => {
    const box = $("#ovLink"), b = $("#ovCopy");
    let ok = false;
    try { await navigator.clipboard.writeText(box.value); ok = true; } catch (e) {}
    if (!ok) { box.focus(); box.select(); try { ok = document.execCommand("copy"); } catch (e) {} }
    b.textContent = ok ? "Copied!" : "Press Ctrl+C";
    setTimeout(() => b.textContent = "Copy", 1800);
  };
  $("#ovSave").onclick = () => {
    const a = document.createElement("a");
    a.href = URL.createObjectURL(new Blob([OVERLAY_HTML], { type: "text/html" }));
    a.download = "chat-overlay.html";
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(() => URL.revokeObjectURL(a.href), 1000);
  };

  // ---------- start ----------
  document.querySelector('.tabs button[data-tab="overlay"]').addEventListener("click", () => { ensure(); refreshInfo(); refreshSources(); });
  refreshInfo();
  if (ls.get("streamhub.tab", "") === "overlay") ensure();
})();
